/**
 * Domain logic for Sequences & Difference Ladders (Knot L4).
 *
 * Core concepts:
 * - A sequence is an ordered list of terms generated by an invariant rule.
 * - First differences reveal arithmetic patterns (constant addition/subtraction).
 * - Common ratios reveal geometric patterns (constant multiplication).
 * - Prediction of next term and distant nth terms without guess-work.
 */

export interface SequenceAnalysis {
  isArithmetic: boolean;
  commonDifference?: number;
  isGeometric: boolean;
  commonRatio?: number;
  firstDifferences: number[];
}

/**
 * Calculates first differences between consecutive terms: d_i = t_{i+1} - t_i.
 */
export function findFirstDifferences(terms: number[]): number[] {
  if (terms.length < 2) return [];
  const diffs: number[] = [];
  for (let i = 0; i < terms.length - 1; i++) {
    diffs.push(terms[i + 1]! - terms[i]!);
  }
  return diffs;
}

/**
 * Determines whether terms form an arithmetic sequence with a constant difference.
 */
export function isArithmeticSequence(terms: number[]): {
  valid: boolean;
  commonDifference?: number;
} {
  if (terms.length < 2) return { valid: false };
  const diffs = findFirstDifferences(terms);
  const d0 = diffs[0];
  const allMatch = diffs.every((d) => d === d0);
  return allMatch ? { valid: true, commonDifference: d0 } : { valid: false };
}

/**
 * Determines whether terms form a geometric sequence with a constant ratio.
 */
export function isGeometricSequence(terms: number[]): {
  valid: boolean;
  commonRatio?: number;
} {
  if (terms.length < 2) return { valid: false };
  if (terms.some((t) => t === 0)) return { valid: false };

  const r0 = terms[1]! / terms[0]!;
  for (let i = 1; i < terms.length - 1; i++) {
    if (terms[i + 1]! / terms[i]! !== r0) {
      return { valid: false };
    }
  }
  return { valid: true, commonRatio: r0 };
}

/**
 * Predicts the next term in a sequence based on arithmetic or geometric rule.
 */
export function predictNextTerm(terms: number[]): number {
  if (terms.length === 0) return 0;
  if (terms.length === 1) return terms[0] ?? 0;

  const lastTerm = terms[terms.length - 1] ?? 0;

  const arith = isArithmeticSequence(terms);
  if (arith.valid && arith.commonDifference !== undefined) {
    return lastTerm + arith.commonDifference;
  }

  const geom = isGeometricSequence(terms);
  if (geom.valid && geom.commonRatio !== undefined) {
    return lastTerm * geom.commonRatio;
  }

  // Fallback: use last difference
  const diffs = findFirstDifferences(terms);
  return lastTerm + (diffs[diffs.length - 1] ?? 0);
}

/**
 * Calculates the nth term directly for an arithmetic progression (1-indexed).
 * a_n = a_1 + (n - 1) * d
 */
export function predictNthTerm(firstTerm: number, commonDifference: number, n: number): number {
  if (n <= 1) return firstTerm;
  return firstTerm + (n - 1) * commonDifference;
}

